begin;

-- Startup Automatic receipts belong to the initial immutable snapshot transaction.
-- Existing v1 calls remain unchanged and do not backfill historical version-one events.
alter table app_private.battle_events drop constraint battle_events_battle_version_check;
alter table app_private.battle_events add constraint battle_events_battle_version_check check (battle_version >= 1);
alter table app_private.battle_privacy_journal drop constraint battle_privacy_journal_battle_version_check;
alter table app_private.battle_privacy_journal add constraint battle_privacy_journal_battle_version_check check (battle_version >= 1);

create function app_private.append_battle_startup_events_v1(
  p_session_id uuid, p_start_snapshot jsonb, p_final_snapshot jsonb,
  p_events jsonb, p_journal jsonb, p_created_at timestamptz
) returns void
language plpgsql
set search_path = pg_catalog, app_private
as $$
declare
  v_actor text := p_start_snapshot #>> '{tactical,battle,currentTurn,combatantId}';
  v_team text;
  v_override jsonb;
  v_visibility jsonb;
  v_index integer;
  v_indexes integer[] := array[]::integer[];
begin
  if not coalesce(
    jsonb_typeof(p_start_snapshot) = 'object' and jsonb_typeof(p_final_snapshot) = 'object'
    and p_start_snapshot #>> '{tactical,battle,lifecycle}' = 'active'
    and p_final_snapshot #>> '{tactical,battle,lifecycle}' in ('active','completed')
    and p_start_snapshot #>> '{tactical,battle,battleId}' = p_final_snapshot #>> '{tactical,battle,battleId}'
    and p_start_snapshot #>> '{tactical,battle,rulesVersion}' = p_final_snapshot #>> '{tactical,battle,rulesVersion}'
    and p_start_snapshot #>> '{tactical,battle,contentVersion}' = p_final_snapshot #>> '{tactical,battle,contentVersion}'
    and jsonb_typeof(p_start_snapshot #> '{tactical,battle,combatants}') = 'array'
    and jsonb_typeof(p_final_snapshot #> '{tactical,battle,combatants}') = 'array'
    and jsonb_typeof(p_events) = 'array'
    and jsonb_typeof(p_journal) = 'object'
    and p_journal -> 'schemaVersion' = '1'::jsonb
    and jsonb_typeof(p_journal -> 'eventVisibilityOverrides') = 'array', false)
  then raise exception using errcode='22023', message='BATTLE_STARTUP_INVALID'; end if;
  if exists(select 1 from jsonb_object_keys(p_journal) k where k not in ('schemaVersion','commandVisibility','eventVisibilityOverrides'))
    or exists(select 1 from jsonb_array_elements(p_events) e where jsonb_typeof(e) <> 'object' or jsonb_typeof(e->'event') <> 'string' or nullif(btrim(e->>'event'),'') is null)
    or (select jsonb_agg(jsonb_build_array(c->>'id',c->>'teamId') order by c->>'id') from jsonb_array_elements(p_start_snapshot #> '{tactical,battle,combatants}') c)
      is distinct from (select jsonb_agg(jsonb_build_array(c->>'id',c->>'teamId') order by c->>'id') from jsonb_array_elements(p_final_snapshot #> '{tactical,battle,combatants}') c)
  then raise exception using errcode='22023', message='BATTLE_STARTUP_INVALID'; end if;
  select c->>'teamId' into v_team from jsonb_array_elements(p_start_snapshot #> '{tactical,battle,combatants}') c where c->>'id'=v_actor;
  if nullif(btrim(v_actor),'') is null or nullif(btrim(v_team),'') is null
  then raise exception using errcode='22023', message='BATTLE_STARTUP_INVALID'; end if;
  for v_override in select e from jsonb_array_elements(p_journal->'eventVisibilityOverrides') e loop
    if not coalesce(jsonb_typeof(v_override)='object' and jsonb_typeof(v_override->'eventIndex')='number' and (v_override->>'eventIndex') ~ '^[0-9]+$',false)
      or exists(select 1 from jsonb_object_keys(v_override) k where k not in ('eventIndex','visibility'))
    then raise exception using errcode='22023', message='BATTLE_STARTUP_INVALID'; end if;
    begin v_index := (v_override->>'eventIndex')::integer;
    exception when numeric_value_out_of_range then raise exception using errcode='22023', message='BATTLE_STARTUP_INVALID'; end;
    if v_index >= jsonb_array_length(p_events) or v_index=any(v_indexes)
    then raise exception using errcode='22023', message='BATTLE_STARTUP_INVALID'; end if;
    v_indexes := array_append(v_indexes,v_index);
  end loop;
  for v_visibility in select p_journal->'commandVisibility' union all select e->'visibility' from jsonb_array_elements(p_journal->'eventVisibilityOverrides') e loop
    if not coalesce(app_private.is_battle_privacy_visibility_v1(v_visibility),false)
      or exists(select 1 from jsonb_object_keys(v_visibility) k where k not in ('kind','teamId','requiredTeamIds'))
      or (v_visibility->>'kind'='public' and v_visibility ? 'requiredTeamIds')
      or (v_visibility->>'kind'='team-only' and not exists(select 1 from jsonb_array_elements(p_start_snapshot #> '{tactical,battle,combatants}') c where c->>'teamId'=v_visibility->>'teamId'))
    then raise exception using errcode='22023', message='BATTLE_STARTUP_INVALID'; end if;
    if v_visibility ? 'requiredTeamIds' then
      if jsonb_typeof(v_visibility->'requiredTeamIds') <> 'array'
      then raise exception using errcode='22023', message='BATTLE_STARTUP_INVALID'; end if;
      if jsonb_array_length(v_visibility->'requiredTeamIds') not between 1 and 6
        or exists(select 1 from jsonb_array_elements(v_visibility->'requiredTeamIds') t where jsonb_typeof(t)<>'string' or t#>>'{}'=v_visibility->>'teamId' or not exists(select 1 from jsonb_array_elements(p_start_snapshot #> '{tactical,battle,combatants}') c where c->>'teamId'=t#>>'{}'))
        or (select count(*) from jsonb_array_elements(v_visibility->'requiredTeamIds')) <> (select count(distinct t) from jsonb_array_elements(v_visibility->'requiredTeamIds') t)
      then raise exception using errcode='22023', message='BATTLE_STARTUP_INVALID'; end if;
    end if;
  end loop;
  update app_private.battle_sessions set current_snapshot=p_final_snapshot, lifecycle=p_final_snapshot#>>'{tactical,battle,lifecycle}' where id=p_session_id;
  update app_private.battle_snapshots set snapshot=p_final_snapshot where battle_session_id=p_session_id and battle_version=1;
  insert into app_private.battle_events(battle_session_id,battle_version,event_index,event,created_at)
    select p_session_id,1,(e.ordinality-1)::integer,e.value,p_created_at from jsonb_array_elements(p_events) with ordinality e(value,ordinality);
  insert into app_private.battle_privacy_journal(battle_session_id,battle_version,journal,created_at)
    values(p_session_id,1,jsonb_build_object('schemaVersion',1,'actorCombatantId',v_actor,'actorTeamId',v_team,'commandVisibility',p_journal->'commandVisibility','eventVisibilityOverrides',p_journal->'eventVisibilityOverrides','eventCount',jsonb_array_length(p_events)),p_created_at);
end;
$$;
revoke all on function app_private.append_battle_startup_events_v1(uuid,jsonb,jsonb,jsonb,jsonb,timestamptz) from public,anon,authenticated,service_role;

create function public.create_battle_session_v2(
  p_actor_key text,p_idempotency_key uuid,p_request_fingerprint text,p_user_id uuid,
  p_battle_id text,p_rules_version integer,p_content_version integer,p_initial_snapshot jsonb,
  p_participants jsonb,p_start_snapshot jsonb,p_initial_events jsonb,p_privacy_journal jsonb
) returns table(battle_session_id uuid,battle_version bigint,snapshot jsonb,created_at timestamptz,replayed boolean)
language plpgsql security definer set search_path=pg_catalog,app_private,public
as $$
declare v_created record;
begin
  select * into v_created from public.create_battle_session_v1(p_actor_key,p_idempotency_key,p_request_fingerprint,p_user_id,p_battle_id,p_rules_version,p_content_version,p_start_snapshot,p_participants);
  if v_created.replayed then
    return query select v_created.battle_session_id,v_created.battle_version,v_created.snapshot,v_created.created_at,true;
    return;
  end if;
  perform app_private.append_battle_startup_events_v1(v_created.battle_session_id,p_start_snapshot,p_initial_snapshot,p_initial_events,p_privacy_journal,v_created.created_at);
  return query select v_created.battle_session_id,v_created.battle_version,p_initial_snapshot,v_created.created_at,false;
end;
$$;
revoke all on function public.create_battle_session_v2(text,uuid,text,uuid,text,integer,integer,jsonb,jsonb,jsonb,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.create_battle_session_v2(text,uuid,text,uuid,text,integer,integer,jsonb,jsonb,jsonb,jsonb,jsonb) to service_role;

create function public.create_pvp_battle_session_v2(
  p_actor_user_id uuid,p_lobby_id uuid,p_battle_id text,p_rules_version integer,p_content_version integer,
  p_initial_snapshot jsonb,p_participants jsonb,p_start_snapshot jsonb,p_initial_events jsonb,p_privacy_journal jsonb
) returns table(battle_session_id uuid,battle_version bigint,snapshot jsonb,created_at timestamptz,battle_key text)
language plpgsql security definer set search_path=pg_catalog,app_private,public
as $$
declare v_created record; v_existing uuid;
begin
  -- Share the predecessor's locked lobby authority; a retry never appends startup rows.
  select l.battle_session_id into v_existing from app_private.pvp_lobbies l where l.id=p_lobby_id for update;
  select * into v_created from public.create_pvp_battle_session_v1(p_actor_user_id,p_lobby_id,p_battle_id,p_rules_version,p_content_version,p_start_snapshot,p_participants);
  if v_existing is not null then
    return query select v_created.battle_session_id,v_created.battle_version,v_created.snapshot,v_created.created_at,v_created.battle_key;
    return;
  end if;
  perform app_private.append_battle_startup_events_v1(v_created.battle_session_id,p_start_snapshot,p_initial_snapshot,p_initial_events,p_privacy_journal,v_created.created_at);
  return query select v_created.battle_session_id,v_created.battle_version,p_initial_snapshot,v_created.created_at,v_created.battle_key;
end;
$$;
revoke all on function public.create_pvp_battle_session_v2(uuid,uuid,text,integer,integer,jsonb,jsonb,jsonb,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.create_pvp_battle_session_v2(uuid,uuid,text,integer,integer,jsonb,jsonb,jsonb,jsonb,jsonb) to service_role;

commit;

begin;

-- Server-projected subscriptions only. Browsers cannot register scenes or read this table.
create table app_private.world_scene_subscriptions (
  character_id uuid primary key references public.characters(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  registered_version bigint not null check (registered_version > 0),
  scene_sector_ids text[] not null check (
    cardinality(scene_sector_ids) between 1 and 25
    and array_ndims(scene_sector_ids) = 1
    and array_position(scene_sector_ids, null) is null
  ),
  initial_position jsonb not null check (jsonb_typeof(initial_position) = 'object'),
  expires_at timestamptz not null
);
create index world_scene_subscriptions_owner_expiry_idx
  on app_private.world_scene_subscriptions(user_id, expires_at);
alter table app_private.world_scene_subscriptions enable row level security;
revoke all on app_private.world_scene_subscriptions from public, anon, authenticated, service_role;

create function public.read_world_scene_players_v2(
  p_user_id uuid,
  p_character_id uuid,
  p_expected_version bigint,
  p_scene_sector_ids text[],
  p_initial_position jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, app_private, public
as $$
declare
  v_state jsonb;
  v_players jsonb;
  v_ids text[];
  v_now timestamptz;
  v_clock bigint;
begin
  -- Preserve character -> world lock order; hold the matching state through registration.
  perform 1 from public.characters c
  where c.id = p_character_id and c.user_id = p_user_id
    and not exists (select 1 from app_private.character_deletion_requests d where d.character_id = c.id)
  for key share;
  if not found then raise exception 'WORLD_NOT_OWNED' using errcode = '42501'; end if;
  select w.state into v_state from app_private.character_world_state w
  where w.character_id = p_character_id for share;
  if v_state is null then raise exception 'WORLD_NOT_OWNED' using errcode = '42501'; end if;
  if p_scene_sector_ids is null or cardinality(p_scene_sector_ids) not between 1 and 25
    or array_ndims(p_scene_sector_ids) <> 1
    or exists (select 1 from unnest(p_scene_sector_ids) s(id) where id is null or length(id) not between 1 and 200)
    or p_initial_position is null or jsonb_typeof(p_initial_position) <> 'object' then
    raise exception 'WORLD_INVALID_SCENE' using errcode = '22023';
  end if;
  v_now := clock_timestamp();
  v_clock := floor(extract(epoch from v_now) * 1000);
  if p_expected_version is null or (v_state->>'version')::bigint <> p_expected_version then
    return jsonb_build_object('version', (v_state->>'version')::bigint, 'serverNow', v_clock, 'players', '[]'::jsonb);
  end if;
  select array_agg(id order by id) into v_ids from (select distinct id from unnest(p_scene_sector_ids) s(id)) q;
  insert into app_private.world_scene_subscriptions as registration(character_id, user_id, registered_version, scene_sector_ids, initial_position, expires_at)
  values(p_character_id, p_user_id, p_expected_version, v_ids, p_initial_position, v_now + interval '2 minutes')
  on conflict(character_id) do update
    set user_id = excluded.user_id, registered_version = excluded.registered_version,
        scene_sector_ids = excluded.scene_sector_ids,
        initial_position = excluded.initial_position, expires_at = excluded.expires_at
    where registration.user_id is distinct from excluded.user_id
      or registration.registered_version is distinct from excluded.registered_version
      or registration.scene_sector_ids is distinct from excluded.scene_sector_ids
      or registration.initial_position is distinct from excluded.initial_position
      or registration.expires_at < v_now + interval '80 seconds';

  -- This service-only result is filtered against the owner's known, supplied terrain by
  -- the server before serialization. Never include destinations, discoveries or route tails.
  select coalesce(jsonb_agg(q.payload order by q.online desc, q.lvl desc, q.nm, q.cid), '[]'::jsonb)
  into v_players from (
    select c.id as cid, c.name as nm, c.level as lvl,
      (w.character_id is not null and w.last_seen_at > v_now - interval '40 seconds') as online,
      jsonb_build_object(
        'characterId', c.id, 'name', c.name, 'level', c.level,
        'portraitRef', c.portrait_ref, 'imageUrl', null,
        'position', coalesce(w.state->'position', p_initial_position),
        'online', (w.character_id is not null and w.last_seen_at > v_now - interval '40 seconds'),
        'attackable', (w.character_id is not null and w.last_seen_at > v_now - interval '40 seconds'
          and app_private.world_block_reason_v1(c.user_id, c.id) is null)
      ) || case when w.character_id is null then '{}'::jsonb else jsonb_build_object(
        'movement', jsonb_build_object(
          'version', (w.state->>'version')::bigint, 'serverNow', v_clock,
          'nextStepAt', w.state->'nextStepAt',
          'route', (select coalesce(jsonb_agg(step order by ord), '[]'::jsonb)
            from jsonb_array_elements(w.state->'route') with ordinality as r(step, ord) where ord <= 12)
        )
      ) end as payload
    from public.characters c
    left join app_private.character_world_state w on w.character_id = c.id
    where coalesce(w.sector_id, p_initial_position->>'sectorId') = any(v_ids)
      and (coalesce((w.state->>'safe')::boolean, true)
        or (w.character_id is not null and w.last_seen_at > v_now - interval '10 minutes'))
      and c.user_id <> p_user_id
      and not exists (select 1 from app_private.character_deletion_requests d where d.character_id = c.id)
    order by online desc, c.level desc, c.name, c.id
    limit 200
  ) q;
  return jsonb_build_object('version', p_expected_version, 'serverNow', v_clock, 'players', v_players);
end;
$$;
revoke all on function public.read_world_scene_players_v2(uuid, uuid, bigint, text[], jsonb)
  from public, anon, authenticated;
grant execute on function public.read_world_scene_players_v2(uuid, uuid, bigint, text[], jsonb)
  to service_role;

create function public.read_world_live_players_v1(
  p_user_id uuid,
  p_character_id uuid,
  p_expected_version bigint
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, app_private, public
as $$
declare
  v_state jsonb;
  v_registration app_private.world_scene_subscriptions%rowtype;
  v_scene jsonb;
begin
  perform 1 from public.characters c
  where c.id = p_character_id and c.user_id = p_user_id
    and not exists (select 1 from app_private.character_deletion_requests d where d.character_id = c.id)
  for key share;
  if not found then raise exception 'WORLD_NOT_OWNED' using errcode = '42501'; end if;
  select w.state into v_state from app_private.character_world_state w
  where w.character_id = p_character_id for share;
  if v_state is null then raise exception 'WORLD_NOT_OWNED' using errcode = '42501'; end if;
  select * into v_registration from app_private.world_scene_subscriptions s
  where s.character_id = p_character_id and s.user_id = p_user_id and s.expires_at > clock_timestamp()
    and s.registered_version = (v_state->>'version')::bigint;
  if not found or p_expected_version is null or (v_state->>'version')::bigint <> p_expected_version then
    return jsonb_build_object(
      'version', (v_state->>'version')::bigint, 'serverNow', floor(extract(epoch from clock_timestamp()) * 1000),
      'state', v_state, 'sceneSectorIds', '[]'::jsonb, 'players', '[]'::jsonb, 'registered', false
    );
  end if;
  -- There is deliberately no sector argument. Only the service-registered scene can be read.
  v_scene := public.read_world_scene_players_v2(p_user_id, p_character_id, p_expected_version,
    v_registration.scene_sector_ids, v_registration.initial_position);
  return v_scene || jsonb_build_object(
    'state', v_state, 'sceneSectorIds', to_jsonb(v_registration.scene_sector_ids), 'registered', true
  );
end;
$$;
revoke all on function public.read_world_live_players_v1(uuid, uuid, bigint)
  from public, anon, authenticated;
grant execute on function public.read_world_live_players_v1(uuid, uuid, bigint)
  to service_role;

create function public.can_receive_world_scene_v1(p_topic text)
returns boolean
language sql
security definer
set search_path = pg_catalog, app_private, public
as $$
  select exists (
    select 1 from app_private.world_scene_subscriptions s
    join public.characters c on c.id = s.character_id and c.user_id = s.user_id
    join app_private.character_world_state w on w.character_id = s.character_id
      and (w.state->>'version')::bigint = s.registered_version
    where s.user_id = (select auth.uid()) and s.expires_at > clock_timestamp()
      and not exists (select 1 from app_private.character_deletion_requests d where d.character_id = c.id)
      and p_topic = any(array(select 'world-scene:' || id from unnest(s.scene_sector_ids) scene(id)))
  );
$$;
revoke all on function public.can_receive_world_scene_v1(text) from public, anon, authenticated;
grant execute on function public.can_receive_world_scene_v1(text) to authenticated;

-- Supabase caches channel receive authorization at join/JWT refresh. Every live presence
-- read still rechecks current ownership, expiry and version; notifications carry no state.
create policy world_scene_receive_v1 on realtime.messages
for select to authenticated
using (
  extension = 'broadcast' and topic = (select realtime.topic())
  and public.can_receive_world_scene_v1((select realtime.topic()))
);
-- No INSERT policy: authenticated browsers cannot publish World scene invalidations.

create function app_private.broadcast_world_scene_change_v1()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, app_private
as $$
declare v_sector text;
begin
  if old.state->'version' is not distinct from new.state->'version' then return null; end if;
  for v_sector in
    select distinct sector_id from (values(old.sector_id), (new.sector_id)) sectors(sector_id)
    where sector_id is not null
  loop
    perform realtime.send('{}'::jsonb, 'changed', 'world-scene:' || v_sector, true);
  end loop;
  return null;
end;
$$;
revoke all on function app_private.broadcast_world_scene_change_v1() from public, anon, authenticated, service_role;
create trigger world_scene_changed_v1
after update of state on app_private.character_world_state
for each row
when (old.state->'version' is distinct from new.state->'version')
execute function app_private.broadcast_world_scene_change_v1();

commit;

begin;

-- Extend world admission without replacing its ordered locks, movement/build
-- rechecks, participant ownership checks or route interruption transaction.
-- Existing callers and historical encounters continue to use the v1 interface.
create function public.start_world_encounter_v2(
  p_user_id uuid,
  p_character_id uuid,
  p_target_id uuid,
  p_expected_version bigint,
  p_target_version bigint,
  p_snapshot jsonb,
  p_build_versions jsonb,
  p_start_snapshot jsonb,
  p_initial_events jsonb,
  p_privacy_journal jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, app_private, public
as $$
declare
  v_result jsonb;
  v_session_id uuid;
  v_created_at timestamptz;
begin
  v_result := public.start_world_encounter_v1(
    p_user_id, p_character_id, p_target_id, p_expected_version, p_target_version,
    p_start_snapshot, p_build_versions
  );
  v_session_id := (v_result ->> 'battleSessionId')::uuid;
  select s.created_at into strict v_created_at
  from app_private.battle_sessions s where s.id = v_session_id;

  -- Any failure rolls back the predecessor's lobby, members, encounter and
  -- interrupted routes as well as all startup state and receipts. Retries still
  -- pass through v1's world-version and active-battle authority before appending.
  perform app_private.append_battle_startup_events_v1(
    v_session_id, p_start_snapshot, p_snapshot,
    p_initial_events, p_privacy_journal, v_created_at
  );
  return v_result;
end;
$$;

revoke all on function public.start_world_encounter_v2(uuid,uuid,uuid,bigint,bigint,jsonb,jsonb,jsonb,jsonb,jsonb)
  from public, anon, authenticated;
grant execute on function public.start_world_encounter_v2(uuid,uuid,uuid,bigint,bigint,jsonb,jsonb,jsonb,jsonb,jsonb)
  to service_role;

commit;
